const хавтасӨнгө = [["#b03a2e","#f1543a"],["#0e8a6d","#20c997"],["#2a4ad0","#4a7dff"],["#9a2ab8","#c84ae8"],["#b8860b","#f0a81a"],["#0e7a9a","#17b0d4"],["#6a2ad0","#9457f0"],["#1a9a4a","#34c968"],["#c22a2a","#f04848"],["#d4541a","#ff8a2a"]];
const хэмжээСонголт = ["13 × 20 см","14 × 21 см","15 × 22 см","12 × 19 см","16 × 23 см"];
const насСонголт = ["8+","12+","15+","18+","Бүх нас"];
function хавтасЗурах(гарчиг, зохиолч, ангилал, өнгө1, өнгө2, загвар) {
  const үгс = String(гарчиг).split(" ");
  const мөрүүд = [];
  let мөр = "";
  үгс.forEach(ү => {    if ((мөр + " " + ү).trim().length > 11 && мөр) { мөрүүд.push(мөр.trim()); мөр = ү; }    else мөр = мөр + " " + ү;  });
  if (мөр.trim()) мөрүүд.push(мөр.trim());
  const үсэгХэмжээ = мөрүүд.some(м => м.length > 9) ? 30 : 34;
  const эхлэхY = 200 - мөрүүд.length * 19;
  const гарчигМөр = мөрүүд.slice(0, 4).map((м, к) =>    "<text x='150' y='" + (эхлэхY + к * 38) + "' font-size='" + үсэгХэмжээ + "' font-weight='bold' text-anchor='middle' fill='white' font-family='sans-serif'>" + м + "</text>").join("");
  let чимэг = "";
  if (загвар === 0) чимэг = "<circle cx='250' cy='60' r='70' fill='white' opacity='0.12'/><circle cx='40' cy='360' r='90' fill='white' opacity='0.10'/><rect x='40' y='60' width='60' height='8' fill='white' opacity='0.7'/>";
  else if (загвар === 1) чимэг = "<rect x='0' y='0' width='300' height='110' fill='black' opacity='0.18'/><circle cx='150' cy='380' r='60' fill='white' opacity='0.12'/><circle cx='150' cy='380' r='38' fill='none' stroke='white' stroke-width='3' opacity='0.5'/>";
  else if (загвар === 2) чимэг = "<path d='M0 90 L300 40 L300 110 L0 160 Z' fill='white' opacity='0.12'/><path d='M0 330 L300 290 L300 350 L0 390 Z' fill='black' opacity='0.15'/>";
  else чимэг = "<circle cx='150' cy='70' r='34' fill='none' stroke='white' stroke-width='4' opacity='0.6'/><rect x='60' y='330' width='180' height='6' fill='white' opacity='0.6'/><rect x='90' y='344' width='120' height='6' fill='white' opacity='0.4'/>";
  const svg = "<svg xmlns='http://www.w3.org/2000/svg' width='300' height='450'>" +    "<defs><linearGradient id='h' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='" + өнгө1 + "'/><stop offset='1' stop-color='" + өнгө2 + "'/></linearGradient></defs>" +    "<rect width='300' height='450' fill='url(#h)'/>" + чимэг +    "<rect x='12' y='12' width='276' height='426' fill='none' stroke='white' stroke-width='2' opacity='0.5'/>" +    "<text x='150' y='44' font-size='14' letter-spacing='3' text-anchor='middle' fill='white' opacity='0.9' font-family='sans-serif'>" + String(ангилал).toUpperCase() + "</text>" +    гарчигМөр +    "<text x='150' y='392' font-size='17' text-anchor='middle' fill='white' font-family='sans-serif'>" + String(зохиолч).slice(0, 26) + "</text></svg>";
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}
function нүүрЗурах(нэр, өнгө1, өнгө2) {
  const эхний = String(нэр).split(" ").map(ү => ү.charAt(0)).slice(0, 2).join("");
  const svg = "<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'>" +    "<defs><linearGradient id='n' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='" + өнгө1 + "'/><stop offset='1' stop-color='" + өнгө2 + "'/></linearGradient></defs>" +    "<rect width='200' height='200' fill='url(#n)'/>" +    "<circle cx='100' cy='78' r='36' fill='white' opacity='0.35'/>" +    "<path d='M40 200 c0-36 28-58 60-58 s60 22 60 58 Z' fill='white' opacity='0.35'/>" +    "<text x='100' y='92' font-size='34' font-weight='bold' text-anchor='middle' fill='white' font-family='sans-serif'>" + эхний + "</text></svg>";
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}
