function захиалгатУнших(түлхүүр, анхны) {
 try {
 const в = JSON.parse(localStorage.getItem(түлхүүр) || "");
 return в == null ? анхны : в;
 } catch (e) {
 return анхны;
 } }
function админБайгаа() {
 try {
 const н = JSON.parse(localStorage.getItem("nevtersen") || "null");
 return !!(н && н.role === "admin");
 } catch (e) {
 return false;
 } }
function нэвтэрсэнАвах() {
 try {
 return JSON.parse(localStorage.getItem("nevtersen") || "null");
 } catch (e) {
 return null;
 } }
