function салбарЗураг(нэр, өнгө1, өнгө2) {
  const svg = "<svg xmlns='http://www.w3.org/2000/svg' width='400' height='300'>" +    "<defs><linearGradient id='s' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#9fc5e8'/><stop offset='1' stop-color='#e8f2fa'/></linearGradient>" +    "<linearGradient id='b' x1='0' y1='0' x2='1' y2='0'><stop offset='0' stop-color='" + өнгө1 + "'/><stop offset='1' stop-color='" + өнгө2 + "'/></linearGradient></defs>" +    "<rect width='400' height='300' fill='url(#s)'/>" +    "<ellipse cx='200' cy='270' rx='150' ry='18' fill='black' opacity='0.12'/>" +    "<rect x='120' y='70' width='160' height='190' fill='url(#b)'/>" +    "<rect x='120' y='70' width='160' height='190' fill='none' stroke='white' stroke-width='3' opacity='0.5'/>" +    "<rect x='140' y='95' width='30' height='30' fill='white' opacity='0.9'/><rect x='180' y='95' width='30' height='30' fill='white' opacity='0.9'/><rect x='220' y='95' width='30' height='30' fill='white' opacity='0.9'/>" +    "<rect x='140' y='135' width='30' height='30' fill='white' opacity='0.9'/><rect x='180' y='135' width='30' height='30' fill='white' opacity='0.9'/><rect x='220' y='135' width='30' height='30' fill='white' opacity='0.9'/>" +    "<rect x='180' y='200' width='40' height='60' fill='#2b1f1a'/>" +    "<rect x='60' y='40' width='280' height='34' rx='8' fill='#2b1f1a' opacity='0.92'/>" +    "<text x='200' y='63' font-size='18' font-weight='bold' text-anchor='middle' fill='white' font-family='sans-serif'>" + нэр + "</text></svg>";
  return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
}
