function салбарЗурах() {
  const эл = document.getElementById("salbarTor");
  if (!эл) return;
  эл.innerHTML = салбарууд.map(с =>    '<div class="salbar-kart"><img class="salbar-photo" src="' + салбарЗураг(с.нэр, с.өнгө1, с.өнгө2) + '" alt="' + с.нэр + ' дэлгүүрийн зураг" loading="lazy">' +    '<div class="salbar-medee"><h3>' + с.нэр + '</h3><p>' + с.хаяг + '</p>' +    '<span class="salbar-tag">🕘 ' + с.цаг + '</span>' +    '<span class="salbar-tag">📞 ' + с.утас + '</span>' +    '<span class="salbar-tag">✉️ ' + с.мэйл + '</span>' +    '<span class="salbar-tag">📍 ' + с.код + '</span></div></div>'  ).join("");
  const тоо = document.getElementById("salbarToo");
  if (тоо) тоо.textContent = салбарууд.length + " салбар";
}
