// Хуучин төлбөрийн хэлбэрүүдийг шинэ 2 сонголт руу шилжүүлэх    
if (н.payDefault !== "Банкны картаар төлөх" && н.payDefault !== "QPay-ээр төлөх") н.payDefault = DEFAULT_SETTINGS.payDefault;
