function өнгөТусгах(т) {
  const root = document.documentElement;
  const preset = ACCENT_PRESETS[т.accent] || ACCENT_PRESETS["улбар"];
  let a1 = preset.a1, a2 = preset.a2, soft = preset.soft, ink = preset.ink;
  if (т.accent === "custom") {
    a1 = (т.colors && т.colors.c1) || preset.a1;
    a2 = (т.colors && т.colors.c2) || preset.a2;
    const r1 = hexRgb(a1) || [232, 147, 90], r2 = hexRgb(a2) || [217, 106, 127];
    soft = "rgba(" + r2[0] + "," + r2[1] + "," + r2[2] + ",.35)";
    ink = hexБараан(a2, 0.3);
  }  let btnText = "#ffffff";
  const гэрэл = өнгөГэрэл(a2);
  if (гэрэл > 0.35) btnText = "#2e1c0e";
  try {
    root.style.setProperty("--acc1", a1);
    root.style.setProperty("--acc2", a2);
    root.style.setProperty("--acc-soft", soft);
    root.style.setProperty("--acc-ink", ink);
    root.style.setProperty("--btn-text", btnText);
    root.style.setProperty("--site-bg", (т.colors && т.colors.bg) || "#fff9f3");
    root.style.setProperty("--site-text", (т.colors && т.colors.tx) || "#4a2c1a");
  } catch (e) {
}}
