function мөнгөТооцоо(тоо) {
  if (тоо == null || isNaN(Number(тоо))) return "0₮";
  if (typeof тоо === "object") return мөнгөТооцоо(тоо.мөнгө || 0);
  return Number(тоо).toLocaleString("mn-MN") + "₮";
}
function одХаруулах(үнэлгээ) {
  let од = "";
  const бүтэн = Math.floor(үнэлгээ);
  for (let i = 0; i < бүтэн; i++) од += "★";
  if (үнэлгээ - бүтэн >= 0.5) од += "☆";
  return од + " " + үнэлгээ;
}
function htmlЭскейп(с) {
 return String(с == null ? "" : с).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
 }
