function номҮнэлгээ(ном) {
  if (!ном) return 0;
  const суурь = Number(ном.rating) || 0;
  let одод = [];
  try {
 одод = сэтгэгдэлАвах(ном.id).map(с => Number(с.од)).filter(о => о >= 1 && о <= 5);
 } catch (e) {
}  if (!одод.length) return суурь;
  const нийлбэр = суурь + одод.reduce((с, о) => с + о, 0);
  return Math.round((нийлбэр / (одод.length + 1)) * 10) / 10;
}
