function саналШинэчлэх() {
  const самбар = document.getElementById("sanalNom");
  if (!самбар) return;
  const тайлбар = document.getElementById("sanalTailbar");
  const админС = захиалгатУнших("adminRec", []).map(window.НомАвах).filter(Boolean);
  const үзсэн = үзсэнАвах();
  const дуртай = sonirholAвах();
  const сүүлийнХайлтууд = хайлтТүүхАвах().slice(-5).map(х => х.q);
  const зохиолчҮзсэн = {
}, ангилалҮзсэн = {
};
  Object.keys(үзсэн).forEach(id => {    const н = window.НомАвах(id);    if (!н) return;    const тоо = Number(үзсэн[id]) || 0;    зохиолчҮзсэн[н.author] = (зохиолчҮзсэн[н.author] || 0) + тоо;    ангилалҮзсэн[н.category] = (ангилалҮзсэн[н.category] || 0) + тоо;  });
  const оноо = (н) => {
    let с = Number(н.rating) || 0;
    if (дуртай.includes(н.id)) с += 4;
    с += Math.min(4, (Number(үзсэн[н.id]) || 0) * 2);
    с += Math.min(3, Number(зохиолчҮзсэн[н.author]) || 0);
    с += Math.min(2, (Number(ангилалҮзсэн[н.category]) || 0) * 0.5);
    const хайлтТекст = (н.title + " " + н.author + " " + н.category + " " + н.topic).toLowerCase();
    сүүлийнХайлтууд.forEach(т => { if (т && хайлтТекст.includes(т)) с += 2; });
    if (сүүлчийнТөрөл && (н.category === сүүлчийнТөрөл || н.topic === сүүлчийнТөрөл)) с += 1.5;
    return с;
  };
  let санал;
  if (админС.length) {
    const үлдсэн = [...номнууд].filter(n => !админС.some(с => с.id === n.id)).sort((a, b) => оноо(b) - оноо(a));
    санал = [...админС, ...үлдсэн].slice(0, 10);
    if (тайлбар) тайлбар.textContent = "Админы санал + таны хайлт, үзсэн, сонирхсон номуудад үндэслэв.";
  } else {
    const идэвх = сүүлийнХайлтууд.length || Object.keys(үзсэн).length || дуртай.length;
    санал = [...номнууд].sort((a, b) => оноо(b) - оноо(a) || b.rating - a.rating).slice(0, 10);
    if (тайлбар) тайлбар.textContent = идэвх      ? "Таны хайлт (" + сүүлийнХайлтууд.length + "), үзсэн (" + Object.keys(үзсэн).length + ") болон сонирхсон (" + дуртай.length + ") номуудад үндэслэн санал болгож байна."      : "Хайлт хийсний дараа танд тохирсон ном санал болгоно.";
  }  жагсаалтЗурах("sanalNom", санал);
}
