// ---------- Онлайн төлбөр: банкны карт + QPay (бодит QR) ----------
// QPay: захиалга баталгаажих хүсэлт хийгдсэний дараа сервер QPay-д бодит
// инвойс үүсгэж, түүний qr_code / qr_image_url-ээр QR кодыг дүрсэлж харуулна.
// Серверийн QP_CODE, QP_SECRET, QP_INVOICE_CODE тохиргоо байхгүй бол QR
// ирэхгүй — зохиомол QR хуурамчаар харуулахгүй, тохиргооны чиглэл харагдана.
const ТОЛБОР_АРГУУД = ["Банкны картаар төлөх", "QPay-ээр төлөх"];
let толборИлгээжБайна = false;
