function толборАргаАвах() {
 const эл = document.getElementById("tolborHelber");
 const в = эл ? эл.value : "";
 return ТОЛБОР_АРГУУД.includes(в) ? в : ТОЛБОР_АРГУУД[0];
 }
function картЦифр(с) {
 return String(с || "").replace(/\D/g, "");
 }
function картБрэнд(цифр) {
  цифр = картЦифр(цифр);
  if (/^4/.test(цифр)) return "Visa";
  if (/^(5[1-5]|2[2-7])/.test(цифр)) return "Mastercard";
  if (/^62/.test(цифр)) return "UnionPay";
  if (/^3[47]/.test(цифр)) return "Amex";
  return "";
}
function лунШалгах(цифр) {
  цифр = картЦифр(цифр);
  if (цифр.length < 15 || цифр.length > 19) return false;
  let нийлбэр = 0, хоёр = false;
  for (let i = цифр.length - 1; i >= 0; i--) {
 let о = Number(цифр[i]);
 if (хоёр) { о *= 2; if (о > 9) о -= 9; } нийлбэр += о;
 хоёр = !хоёр;
 }  return нийлбэр % 10 === 0;
}
function картВалидац(оролт) {
  const нэр = String(оролт.нэр || "").trim();
  const цифр = картЦифр(оролт.дугаар);
  const хугацаа = String(оролт.хугацаа || "").trim();
  const cvv = String(оролт.cvv || "").trim();
  if (!нэр) return {
 ok: false, алдаа: "Карт эзэмшигчийн нэрийг оруулна уу." };
  if (цифр.length < 12 || цифр.length > 19) return {
 ok: false, алдаа: "Картын дугаар 12–19 тоо байх ёстой." };
  const таарах = хугацаа.match(/^(0[1-9]|1[0-2])\/(\d{2})$/);
  if (!таарах) return {
 ok: false, алдаа: "Дуусах хугацааг MM/YY форматаар оруулна уу." };
  if (!/^\d{3,4}$/.test(cvv)) return {
 ok: false, алдаа: "CVV/CVC код 3–4 оронтой байх ёстой." };
  return {
 ok: true, брэнд: картБрэнд(цифр) || "Карт", сүүл4: цифр.slice(-4) };
}
