// Бодит инвойсын QR-ийг дүрсэлнэ: эхлээд QPay-ийн өөрийн зураг, тийм бол
// хэрэггүй qr_code тэмдэгтээс QR дүрсэлэгч сангийн (qrcode.min.js) тусламжтай.
function qpayQRДүрсэл(д) {
  const эр = document.getElementById("qpayQr");
  if (!эр) return;
  эр.innerHTML = "";
  if (д.qrЗурагUrl) {
    const з = document.createElement("img");
    з.className = "qpay-qr-зураг";
    з.src = д.qrЗурагUrl;
    з.alt = "QPay QR код";
    эр.appendChild(з);
  } else if (д.qrТекст) {
    if (window.QRCode && window.QRCode.CorrectLevel) {
      const ор = document.createElement("div");
      ор.className = "qpay-qr-ор";
      эр.appendChild(ор);
      try { new window.QRCode(ор, { text: String(д.qrТекст), width: 228, height: 228, correctLevel: window.QRCode.CorrectLevel.M }); }
      catch (e) { эр.innerHTML = '<div class="qpay-qr-алдаа">QR кодыг дүрсэлж чадсангүй. "Шинэ QR авах" товчийг дахин дарна уу.</div>'; }
    } else эр.innerHTML = '<div class="qpay-qr-алдаа">QR дүрсэлэгч санг (qrcode.min.js) ачааллаж чадсангүй. Хуудсыг шинэчилж дахин оролдоно уу.</div>';
  } else эр.innerHTML = '<div class="qpay-qr-алдаа">QR код байхгүй байна. "Шинэ QR авах" товчийг дахин дарна уу.</div>';
}
