  алхам(() => { try { хүргэлтМэдээлэлШинэчлэх(); } catch (e) {} });
  алхам(() => { try { хэрэглэгчТүрээсХураангуй(); } catch (e) {} });
  алхам(() => { try { түрээсСануулгаШалгах(); } catch (e) {} });
